        }
    }
}

cleanCopy(object?: any, ...rest: any[]): any {
  var copy: any = angular.copy(object);
  for (var prop in copy) {
      if (prop && prop.startsWith('$$')) {
          delete copy[prop];
      }
  }
  return copy;
}

