export class TbJsonToStringDirective implements ControlValueAccessor {
  protected readonly element = inject(ElementRef);

  private onChange: (value: any) => void = () => {};
  private onTouched: () => void = () => {};

  registerOnChange(fn: (value: any) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  writeValue(value: any): void {
    this.element.nativeElement.value = this.out(value);
  }

  onInput(value: any): void {
    this.onChange(this.into(value));
  }

  into = (input?: any, ...rest: any[]): { value: any; valid: boolean } | any => {
    try {
        const value = JSON.parse(input);
        return value;
    } catch (e: any) {
    }
    return undefined;
  };

  out = (data?: any, ...rest: any[]): any => {
    try {
        return JSON.stringify(data);
    } catch (e: any) {
    }
    return undefined;
  };
}

function KeyValMapController(this: any) {

    let vm: any = this;

    vm.kvList = [];

    vm.removeKeyVal = removeKeyVal;
    vm.addKeyVal = addKeyVal;

    vm.ngOnChanges = () => {
        stopWatchKvList();
        vm.kvList.length = 0;
        if (vm.keyValMap) {
            for (var property in vm.keyValMap) {
                if (Object.prototype.hasOwnProperty.call(vm.keyValMap, property)) {
                    vm.kvList.push(
                        {
                            key: property + '',
                            value: vm.keyValMap[property]
                        }
                    );
                }
            }
        }
        watchKvList();
    };

    let kvListEffectRef: any = null;

    function watchKvList() {
        kvListEffectRef = effect(() => {
            const list = vm.kvList;
            if (!vm.keyValMap) {
                return;
            }
            for (var property in vm.keyValMap) {
                if (Object.prototype.hasOwnProperty.call(vm.keyValMap, property)) {
                    delete vm.keyValMap[property];
                }
            }
            for (var i: any = 0; i < list.length; i++) {
                var entry: any = list[i];
                vm.keyValMap[entry.key] = entry.value;
            }
        });
    }

    function stopWatchKvList() {
        if (kvListEffectRef) {
            kvListEffectRef.destroy();
            kvListEffectRef = null;
        }
    }


    function removeKeyVal(index?: any) {
        if (index > -1) {
            vm.kvList.splice(index, 1);
        }
    }

    function addKeyVal() {
        if (!vm.kvList) {
            vm.kvList = [];
        }
        vm.kvList.push(
            {
                key: '',
                value: ''
            }
        );
    }
}

