private readonly secsEffect = effect(() => {
  const newSecs = this.secs();
  if (newSecs < 0) {
    if ((this.days() + this.hours() + this.mins()) > 0) {
      this.secs.set(newSecs + 60);
      this.mins.update(v => v - 1);
    } else {
      this.secs.set(0);
    }
  } else if (newSecs >= 60) {
    this.secs.set(newSecs - 60);
    this.mins.update(v => v + 1);
  }
  this.updateView();
});

private readonly minsEffect = effect(() => {
  const newMins = this.mins();
  if (newMins < 0) {
    if ((this.days() + this.hours()) > 0) {
      this.mins.set(newMins + 60);
      this.hours.update(v => v - 1);
    } else {
      this.mins.set(0);
    }
  } else if (newMins >= 60) {
    this.mins.set(newMins - 60);
    this.hours.update(v => v + 1);
  }
  this.updateView();
});

private readonly hoursEffect = effect(() => {
  const newHours = this.hours();
  if (newHours < 0) {
    if (this.days() > 0) {
      this.hours.set(newHours + 24);
      this.days.update(v => v - 1);
    } else {
      this.hours.set(0);
    }
  } else if (newHours >= 24) {
    this.hours.set(newHours - 24);
    this.days.update(v => v + 1);
  }
  this.updateView();
});

private readonly daysEffect = effect(() => {
  const newDays = this.days();
  if (newDays < 0) {
    this.days.set(0);
  }
  this.updateView();
});

